-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the seed trigger raises (1/0) BEFORE its tier early return
-- targets: c18
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._seed_checklists_on_plan_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM 1/0;
  IF public.tier_rank((SELECT p.tier FROM public.plans p WHERE p.id = NEW.plan_id))
     < public.tier_rank('team') THEN
    RETURN NULL;
  END IF;
  PERFORM public._seed_org_checklist_templates(NEW.organization_id);
  RETURN NULL;
END
$$;

DO $proof$
BEGIN
  IF NOT (position('PERFORM 1/0' in pg_get_functiondef('public._seed_checklists_on_plan_write()'::regprocedure)) BETWEEN 1 AND position('tier_rank' in pg_get_functiondef('public._seed_checklists_on_plan_write()'::regprocedure))) THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('1/0 before the tier test') AS mutation;
